UPDATE struct_mind_graph
SET name = #{name},
    content = CAST(#{content, typeHandler=com.flydeer.repository.postgres.typehandler.JsonbStringTypeHandler} AS jsonb),
    rev = #{newRev},
    updated_at = #{updatedAt}
WHERE graph_id = #{graphId}
  AND deleted = 0
  AND rev = #{expectedRev}

UPDATE struct_mind_graph
SET name = #{name},
    updated_at = #{updatedAt}
WHERE graph_id = #{graphId}
  AND deleted = 0

UPDATE struct_mind_graph
SET parent_graph_id = #{parentGraphId},
    updated_at = #{updatedAt}
WHERE graph_id = #{graphId}
  AND deleted = 0

UPDATE struct_mind_graph
SET deleted = 1,
    updated_at = #{updatedAt}
WHERE deleted = 0
  AND graph_id IN

  #{id}
